CREATE OR REPLACE FUNCTION public.fc_get_world_state() RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE v_uid text:=public.fc_require_uid(); v_me public.fc_characters; v_pos public.fc_character_positions; v_cell public.fc_world_cells; v_room public.fc_world_rooms; v_home uuid;
BEGIN
 SELECT * INTO v_me FROM public.fc_characters WHERE owner_id=v_uid; IF v_me.id IS NULL THEN RAISE EXCEPTION '请先入世'; END IF;
 v_home:=public.fc_ensure_family_home(v_me.family_id);
 SELECT * INTO v_pos FROM public.fc_character_positions WHERE character_id=v_me.id;
 IF EXISTS(SELECT 1 FROM public.fc_city_journeys WHERE character_id=v_me.id AND arrives_at<=now()) THEN
 SELECT c.* INTO v_cell FROM public.fc_city_journeys j JOIN public.fc_world_rooms r ON r.city_id=j.destination AND (r.template_id='10000000-0000-0000-0000-000000000006' OR r.id='10000000-0000-0000-0000-000000000006') JOIN public.fc_world_cells c ON c.room_id=r.id AND c.x=0 AND c.y=0 WHERE j.character_id=v_me.id;
 UPDATE public.fc_character_positions SET cell_id=v_cell.id WHERE character_id=v_me.id;
 DELETE FROM public.fc_city_journeys WHERE character_id=v_me.id;
 SELECT * INTO v_pos FROM public.fc_character_positions WHERE character_id=v_me.id;
 END IF;
 IF v_pos.cell_id IS NULL THEN
  SELECT * INTO v_cell FROM public.fc_world_cells WHERE room_id=v_home AND x=0 AND y=0;
  INSERT INTO public.fc_character_positions(character_id,cell_id) VALUES(v_me.id,v_cell.id) ON CONFLICT (character_id) DO NOTHING;
  SELECT * INTO v_pos FROM public.fc_character_positions WHERE character_id=v_me.id;
 ELSE
  SELECT * INTO v_cell FROM public.fc_world_cells WHERE id=v_pos.cell_id;
 END IF;
 IF EXISTS(SELECT 1 FROM public.fc_world_rooms r WHERE r.id=v_cell.room_id AND r.family_id IS NULL AND (r.id='10000000-0000-0000-0000-000000000001' OR r.id::text BETWEEN '10000000-0000-0000-0000-000000000010' AND '10000000-0000-0000-0000-000000000022')) THEN
 SELECT * INTO v_cell FROM public.fc_world_cells WHERE id=md5(v_me.family_id::text||':cell:'||v_cell.id::text)::uuid;
 UPDATE public.fc_character_positions SET cell_id=v_cell.id WHERE character_id=v_me.id;
 END IF;
 UPDATE public.fc_character_positions SET updated_at=now() WHERE character_id=v_me.id;
 SELECT * INTO v_room FROM public.fc_world_rooms WHERE id=v_cell.room_id;
 PERFORM public.fc_claim_cultivation();
 RETURN jsonb_build_object('cultivation_safety',jsonb_build_object('city_safe',v_room.is_safe_city,'can_cultivate',v_room.is_safe_city OR EXISTS(SELECT 1 FROM public.fc_defense_setups d WHERE d.character_id=v_me.id AND d.room_id=v_room.id AND d.expires_at>now()) AND NOT EXISTS(SELECT 1 FROM public.fc_city_journeys j WHERE j.character_id=v_me.id),'defense_until',(SELECT expires_at FROM public.fc_defense_setups WHERE character_id=v_me.id AND room_id=v_room.id)),'encounter',(SELECT jsonb_build_object('id',e.id,'monster_name',e.monster_name,'monster_realm_index',e.monster_realm_index,'monster_layer',e.monster_layer,'monster_count',e.monster_count,'status',e.status) FROM public.fc_wild_encounters e WHERE e.character_id=v_me.id AND e.room_id=v_room.id AND e.status='待处理' ORDER BY e.created_at DESC LIMIT 1),'atlas',jsonb_build_object('states',(SELECT jsonb_agg(to_jsonb(s)) FROM public.fc_states s),'cities',(SELECT jsonb_agg(to_jsonb(c)) FROM public.fc_cities c),'roads',(SELECT jsonb_agg(to_jsonb(e)) FROM public.fc_city_roads e)),'journey',(SELECT to_jsonb(j) FROM public.fc_city_journeys j WHERE j.character_id=v_me.id),'room',to_jsonb(v_room),'cell',to_jsonb(v_cell),'cells',(SELECT jsonb_agg(to_jsonb(t) ORDER BY t.y,t.x) FROM public.fc_world_cells t WHERE t.room_id=v_room.id),'exits',coalesce((SELECT jsonb_agg(jsonb_build_object('from_cell',e.from_cell,'x',c.x,'y',c.y,'direction',e.direction,'to_room',CASE WHEN r.id='10000000-0000-0000-0000-000000000001' THEN (SELECT name FROM public.fc_world_rooms WHERE id=v_home) ELSE r.name END)) FROM public.fc_world_exits e JOIN public.fc_world_cells c ON c.id=e.from_cell JOIN public.fc_world_cells dest ON dest.id=e.to_cell JOIN public.fc_world_rooms r ON r.id=dest.room_id WHERE c.room_id=v_room.id),'[]'::jsonb),'navigation',jsonb_build_object('cells',(SELECT jsonb_agg(to_jsonb(c)) FROM public.fc_world_cells c JOIN public.fc_world_rooms r ON r.id=c.room_id WHERE (r.family_id=v_me.family_id AND r.city_id=v_room.city_id OR (r.city_id=v_room.city_id AND r.family_id IS NULL AND r.id<>'10000000-0000-0000-0000-000000000001' AND r.id::text NOT BETWEEN '10000000-0000-0000-0000-000000000010' AND '10000000-0000-0000-0000-000000000022'))),'edges',(SELECT jsonb_agg(jsonb_build_object('from',c.id,'to',n.id,'direction',d.direction)) FROM public.fc_world_cells c JOIN public.fc_world_rooms r ON r.id=c.room_id CROSS JOIN (VALUES ('north'),('south'),('east'),('west')) d(direction) JOIN public.fc_world_cells n ON n.id=CASE WHEN c.room_id='10000000-0000-0000-0000-000000000005' AND c.x=0 AND c.y=-1 AND d.direction='north' THEN (SELECT id FROM public.fc_world_cells WHERE room_id=v_home AND x=0 AND y=1) ELSE public.fc_world_next_cell(c.id,d.direction) END WHERE (r.family_id=v_me.family_id AND r.city_id=v_room.city_id OR (r.city_id=v_room.city_id AND r.family_id IS NULL AND r.id<>'10000000-0000-0000-0000-000000000001' AND r.id::text NOT BETWEEN '10000000-0000-0000-0000-000000000010' AND '10000000-0000-0000-0000-000000000022')) AND EXISTS(SELECT 1 FROM public.fc_world_rooms nr WHERE nr.id=n.room_id AND (nr.family_id IS NULL OR nr.family_id=v_me.family_id)))),'map_rooms',(SELECT jsonb_agg(to_jsonb(r)) FROM public.fc_world_rooms r WHERE (r.family_id=v_me.family_id AND r.city_id=v_room.city_id OR (r.city_id=v_room.city_id AND r.family_id IS NULL AND r.id<>'10000000-0000-0000-0000-000000000001' AND r.id::text NOT BETWEEN '10000000-0000-0000-0000-000000000010' AND '10000000-0000-0000-0000-000000000022'))),'nearby',coalesce((SELECT jsonb_agg(jsonb_build_object('id',c.id,'name',c.display_name,'title',c.title)) FROM public.fc_character_positions p JOIN public.fc_characters c ON c.id=p.character_id WHERE p.cell_id=v_cell.id AND c.id<>v_me.id AND p.updated_at>now()-interval '90 seconds'),'[]'::jsonb));
END $$;
GRANT EXECUTE ON FUNCTION public.fc_get_world_state() TO authenticated;
